int fdwatch_check_event(LPFDWATCH fdw,socket_t fd,uint event_idx)

{
  LPKEVENT pkVar1;
  uint uVar2;
  
  if ((uint)(fdw->nfiles * 2) <= event_idx) {
    __assert("fdwatch_check_event","fdwatch.c",0xad);
  }
  pkVar1 = fdw->kqrevents;
  if (pkVar1[event_idx].ident == fd) {
    if ((pkVar1[event_idx].flags & 0x4000) != 0) {
      return 8;
    }
    if ((short)pkVar1[event_idx].flags < 0) {
      return 8;
    }
    if (pkVar1[event_idx].filter == -1) {
      if ((*(byte *)(fdw->fd_rw + fd) & 1) != 0) {
        return 1;
      }
    }
    else if (pkVar1[event_idx].filter == -2) {
      uVar2 = fdw->fd_rw[fd];
      if ((uVar2 & 2) != 0) {
        if ((uVar2 & 4) != 0) {
          fdw->fd_rw[fd] = uVar2 & 0xfffffffd;
        }
        return 2;
      }
    }
    else {
      _sys_err("fdwatch_check_event",200,"fdwatch_check_event: Unknown filter %d (descriptor %d)",
               (int)pkVar1[event_idx].filter,fd);
    }
  }
  return 0;
}
